/**
 * L5 动力聚变核心 —— 几何与 Prog_HDRCore 着色器
 * 来源：L5 实施说明书 §1（几何）/ §2（材质）/ §7.2 uniform 表 / 附录 B.7
 *
 * 几何（§1.1 / 附录 B.7 / 5.6.1）：
 *  - 内层：固态发光核心，正十二面体，R_core = 0.8u
 *  - 外层：悬浮半透明电磁约束框，外接半径 1.0u，壁厚 0.04u，径向间距 0.20u
 *  - 内外层共用 Prog_HDRCore（57.1：全场景 Shader Program ≤ 5），以 u_shell_id 分支区分
 *
 * ── 视觉增强层 v2（非规格项，见《L5_视觉增强调研报告》§4；可由 stage.setFx(false) 一键回退）──
 *
 * 【v1 的失败与 v2 的修正 —— 逐条对应"为什么之前看不见"】
 *  ① 湍流被平均抹平：v1 用 total/count 沿弦求均值 → 方差衰减 √N≈5.7 倍。
 *     v2 改为**前到后发射-吸收（Beer–Lambert）体积积分**：
 *     acc += T·emit·a; T *= (1-a); a = 1-exp(-σ·ρ·ds)。
 *     近端高密度丝状结构会遮挡其后的一切 → 湍流方差完整保留。
 *  ② 约束壳看不见：v1 用 pow(1-facing, 3.4/5.0) → 面上几乎处处为 0。
 *     v2 改为**低指数宽边缘光** pow(1-facing, 1.5) + 常数底亮 + 移动干涉条纹。
 *  ③ 硬壳无机械感：v1 外壳是纯加色发光，叠在已很亮的核心上被 ACES 压平。
 *     v2 外壳改为**暗色半透明硬壳 + 预乘混合**：暗底着色 + Blinn 镜面高光
 *     + 三轴程序化面板缝（导数抗锯齿，bgolus pristine-grid 思路）+ 宽边缘光。
 *     面板缝 / 边缘光 / 高光以"发光"形式直加，不参与 alpha 稀释 → 在亮核上依然可辨。
 *  ④ 外溢辐射：由 scene.js 的独立辐射链（掩膜 → 半分辨率分离高斯 → 径向光轴）承担。
 *
 *  规格红线（63.2）：任何档位下 L5 的颜色与明度呼吸映射不得关闭。
 *  本文件所有增强项的亮度均由 u_emissive_intensity(E(t)) 与 u_emissive_color 直接驱动。
 */
import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { buildFaceFragments } from './dodecaKit.js';
import { BH_B_CRIT_RS, buildDeflectionLUT } from './geodesic.js';

export const R_CORE = 0.8;      // 5.6.1 内层外接半径
export const R_SHELL_OUT = 1.0; // 附录 B.7 外层外接半径
export const SHELL_WALL = 0.04; // 附录 B.7 外层壁厚
export const R_SHELL_IN = R_SHELL_OUT - SHELL_WALL;

/* v-内容4：黑洞体（核心内部）—— **带厚度的正十二面体机械外壳（完全不透明）** + 中心黑洞。
 *
 * ★★ v-内容4-形（用户 2026-09-29，本轮最严重问题：**基础形状根本不成立**）
 *   用户原话："现在的实现里，黑洞体看着像是三个五边形叠在一起，甚至都不是立体"
 *   根因（实测定位，四个独立 bug 叠加，缺一不可）：
 *     A 面板**尺寸**错：`bhPanelGeo(BH_SHELL_R, …)` 把十二面体的**外接半径**当成
 *       五边形**面**的外接半径。面上五边形外接半径 = R × 0.60706，故面板大了 1.647×。
 *     B 面板**位置**错：position = n × bhLift，而 bhLift 上限只有 0.085 ——
 *       正确应在**内切半径** BH_SHELL_IN(0.20) 处。12 块板全挤在离体心 0.085 的位置
 *       互相穿插 → 屏幕上就是"几个五边形叠在一起"。
 *     C 面板**朝向**错：`setFromUnitVectors(+Z, n)` 只把 +Z 转到法线，绕法线的滚转
 *       是任意的 → 12 块板各自乱转，棱边对不上，拼不成壳。
 *     D 材质 `transparent + depthWrite:false` → 互相看穿，读不出实体。
 *
 * 形态规格（用户定标）：
 *   · 外壳 = 12 块**带厚度**的五边形机械板，完全不透明，闭合时拼成完整十二面体；
 *   · 中心黑洞初始半径 **0.10u**；
 *   · 0.2–0.8：每块板**沿法线抬升，大小不变**，到体心的距离 = **当前黑洞半径 + 0.10u**
 *     （于是板与黑洞表面恒定留 0.1u 的缝，缝里露黑洞）；
 *   · >80：黑洞把**外壳板和所有粒子**一起塌缩吸入（见下三段式）。
 *
 * ★ v-内容4-塌（用户 2026-09-29 第二轮定标，塌缩改**四段式**，顺序不能错）
 *   用户原话："现在的塌缩动画是：黑洞和外壳整体缩小到一个点，这和普通的缩放有什么区别？
 *            我要的是：外壳和所有粒子被黑洞的超强引力吸引卷曲，被吸收到里面，
 *            随后黑洞本身再缩小塌缩（过程中黑洞本身要有引力扭曲的动效）到一个点，
 *            然后才是闪光和放大"
 *   → 关键：**① 阶段黑洞不缩**（旧实现让黑洞跟外壳一起缩，所以看起来就是整体缩放）；
 *     黑洞自己塌缩是 **②**，且必须带引力扭曲动效（u_bh_warp）。四段绝对时长：
 *     ① 吸入   BH_SUCK_DUR  = 1.10s —— 外壳板被卷曲吸进黑洞、缩到 0；
 *        **所有粒子**在这段内被全部吸入且**不重生**；黑洞半径**保持不变**（略胀，正在吞）
 *     ② 塌缩   BH_PINCH_DUR = 0.55s —— **黑洞本身**缩小到中心点 BH_R_PINCH，
 *        u_bh_warp 0→1 驱动引力扭曲（光子环涟漪 + 光晕外扩拖拽）
 *     ③ 闪光   BH_FLASH_DUR = 0.45s —— 半径钉在中心点，u_bh_flash 走 sin 半周爆白
 *     ④ 爆发   BH_BURST_DUR = 0.55s —— 半径 easeOutCubic 放大到 BH_R_MAX（0.40u）
 *   总时长 2.65s。
 *
 * ★ v-内容4-视（**事件视界 ≠ 引力透镜**）
 *   用户原话："事件视界是中心的一个黑球……在视野里它是一个完全不会透光的黑色球体，
 *            现在的实现上这个球就像个透明的透镜一样，我甚至可以看见它后面的水晶碎片面"
 *   → 旧实现把两者画在**同一个球**上，且 `transparent + depthWrite:false` →
 *     不写深度、不遮挡任何东西，后面的碎片照常透出来。
 *   正确拆成两个 mesh：
 *     · `bhCore` 事件视界 = **纯黑不透明球**（opaque，写深度）
 *       —— 进入视界的光全被吸收，物理上就是"什么都透不过去"
 *     · `bhLens` 引力透镜/光子环 = 视界**外面**的加色壳（光子球 ≈ 1.5 Rs），
 *       只画光子环与透镜光晕，不遮挡
 *   ★ 半径口径（v5.22-尺）：BH_R_* 是**外径**（含光晕），视界 = 外径 / BH_LENS_K；
 *     外径必须顶在用户定标的 BH_R_MAX = 0.40u 上，不能把透镜壳再往外乘 1.5。 */
/** 正十二面体内切半径 / 外接半径 = 0.79465447…（SDF 支撑函数距离） */
export const DODEC_INRADIUS_RATIO = 0.79465447;
/** 面上五边形的外接半径 / 十二面体外接半径 = sqrt(1 − 0.79465447²) */
export const DODEC_FACE_CIRCUM_RATIO = 0.60706110;
const BH_R_MIN = 0.10;          // 中心黑洞半径（用户定标 0.1u；原 0.055）
const BH_PANEL_GAP = 0.10;      // 面板到体心 = 黑洞半径 + 0.1u（用户定标）
const BH_SHELL_IN = BH_R_MIN + BH_PANEL_GAP;              // 0.20 闭合态面板中心距
const BH_SHELL_R = BH_SHELL_IN / DODEC_INRADIUS_RATIO;    // 0.2517 外壳外接半径
const BH_FACE_R = BH_SHELL_R * DODEC_FACE_CIRCUM_RATIO;   // 0.1528 面板五边形外接半径
const BH_SHELL_K = 0.90;        // 面板内面位似比（机械厚度棱台）
const BH_SHELL_T = 0.032;       // 面板厚度（棱台高）—— 加厚，"带厚度"要看得出来
const BH_R_OPEN_MAX = 0.22;     // <80 挡位的黑洞最大半径（20-80 渐开用）
const BH_R_MAX = 0.40;          // >80 挡位的黑洞最大半径（= 半核心壳 0.8/2）
const BH_R_PINCH = 0.010;       // ②塌缩到的「中心点」半径
const BH_FLASH_R = 0.12;        // ③闪光的爆白可视半径（v5.26：0.20 → 0.12，"耀眼但很小"）
/* v-内容4-视 / v5.22-尺：透镜壳外径与事件视界半径之比（光子球 ≈1.5 Rs）。
 * ★ **BH_R_* 系列半径一律是「整个黑洞（含透镜光晕）的外径」，不是视界半径** ——
 *   视界半径 = 外径 / BH_LENS_K。v5.22 之前把透镜壳做成 bhRDraw × BH_LENS_K，
 *   于是 >80 时外径 0.40 → 0.60u，比用户定标的 0.40u 大了整整 1.5 倍（用户："比之前大了好多"）。
 *   现在改为向内留空间：bhLens.scale = bhRDraw（外径 = BH_R_MAX = 0.40u），
 *   bhCore.scale = bhRDraw / BH_LENS_K（视界 = 0.267u，与 u_bh_vh = 1/1.5 一致）。 */
const BH_LENS_K = 1.50;

/* ── v5.28：透镜环厚度 —— 这是唯一一项我必须先查资料再定的量 ────────────────────
 * 物理事实（用户指出，我此前没对齐）：**施瓦西黑洞第一层光子环的厚度 ≈ 0.015 × 黑洞半径**。
 * 成因：高阶像径向间距按 e^{−2π} ≈ 1.87e−3 收敛，n 阶子环到临界曲线的距离是
 * bu n ∝ e^{−2πn} —— 所以整叠子环是**指数紧贴**在临界曲线上的，不是一条宽带。
 * v5.27 我做了 u ∈ (1, 2.7)（厚度 0.79 × 阴影半径 ≈ 0.21u），是物理值的 ~50 倍，
 * 而且比黑洞本体还粗 —— 用户定性："这算什么东西"。
 *
 *   · 把真正的临界值（=**不可见**，约半个像素）和"为了让用戶看得見而故意加厚多少"
 *     分成两个数摆在一起，逼自己对得上：
 *       LENS_RING_PHYS = 0.015   ← 文献：施瓦西第一层光子环厚度 / 黑洞半径（别动）
 *       LENS_RING_FRAC = 0.25    ← 本项目实际取的厚度 / 阴影半径（唯一推荐旋钮）
 *     于是夸张倍数 = 0.25 / 0.015 ≈ 17×（v5.27 是 53× —— 那就是"一倍半径厚"的由来）。
 *     外径 0.40u 时环宽 0.0667u ≈ 8px（视口 1u≈120px），黑洞本体直径 ≈64px ——
 *     读起来是一条贴在阴影边缘的环，不是一个盘。 */
const LENS_RING_PHYS = 0.015;                        // 文献：第一层光子环厚度 / 黑洞半径
const LENS_RING_FRAC = 0.25;                         // 本项目厚度 / 阴影半径（唯一推荐旋钮）
const LENS_U_OUT = 1.0 + LENS_RING_FRAC;             // = 1.25 环外缘（u = b/b_c）
const LUT_UMAX = 6.0;                                // 偏折角查找表的 u 上限（超出用弱场公式）

/* ★ 绘制顺序总表（v5.30）—— 改任何一处 renderOrder 都必须回来对着这张表看：
 *   18 bhCore          不透明视界球（唯一写深度的遮挡者）
 *   20 bhGrav          测地线透镜环（★ v5.30：写洞心深度，靠"深度"做真替换，不靠排序）
 *   24 bhPanels        黑洞自身机械面板
 *   29/30/31           基准面 / 体积核心 / 内壳
 *   32                 水晶碎片本体 / 前沿柱面 / 碎片内芯（★ v5.32：三者同层，见下）
 *   33                 笼框 / 环境粒子
 *   35 FRAG_DEPTH_ORDER 隐形遮挡体（碎片的"只写深度"孪生体）← 夹在这里才有意义
 * ★ v5.32（用户实测："前后同时有水晶面出来的时候都没有前后遮挡关系"）：
 *   本体/柱面/内芯原来占 32/33/34 三层，而 three.js 的排序键里 **renderOrder 优先于
 *   深度** ⇒ 背面那个面的柱面(33)、内芯(34) 永远画在正面那个面的晶体(32) 之后，
 *   跨面的前后关系被分层压掉。现三者同归 32 ⇒ 12 个面之间恢复按 z 的由远及近排序；
 *   同面内 z 相同 ⇒ 按 id（创建序 本体→内芯→柱面）稳定排序。
 *   38 bhLens          加色光子环 / 挤压亮弧 / 闪光
 * 隐形遮挡体之所以是 35：排在它之前的层一个都不会被影响；排在它之后的只有 38，
 * 而这层正是"应该被洞前碎片遮住"的部分。
 * ★ bhGrav 为什么是 20（v5.30，别再往回挪）：它**写深度**（洞心深度），
 *   排在它之后的层按自身深度自动分流 —— 洞后的被剔除、洞前的照常叠加。
 *   v5.27 排在 20 出现"两张像"，根因是当时 depthWrite:false（洞后内容没被剔除），
 *   不是 20 这个顺序有问题。 */
const FRAG_DEPTH_ORDER = 35;

/* ── v5.27：尺度映射（唯一锚点：临界曲线 = 视界球轮廓 ⇒ 视觉尺寸不变）─────────────
 * 物理上阴影半径 = 2.598 × 视界，照搬会把阴影撑到 1.73×外径（用户定标的外径是 0.40u）。
 * → 保留"阴影边缘正好落在视界球轮廓上"这个锚点，用**有效史瓦西半径**
 *   rs_eff = (外径/BH_LENS_K)/b_c 把测地线函数接上去：偏折角随 b 的**形状仍是严格解**
 *   （geodesic.js 数值积分，node 断言 15/15 通过），只是长度基准落在美术预算里。
 *   u ≡ b/b_c：u = 1 → 临界曲线（= 视界球轮廓 = 0.2667u）；u > 1 逃逸。 */

/* v5.25-节奏（用户定标）："整个塌缩时间太长"，而"膨胀推开碎块"那一段要**更长**。
 * 故前三段压缩（吸入/塌缩/闪光 2.10s → 1.42s），把时间让给 ④ 爆发
 * （0.55s → 0.95s）—— 爆发段正是"黑洞膨胀把水晶碎块面与基准面顶开"的那一段。 */
const BH_SUCK_DUR = 0.70;       // ① 吸入：外壳 + 所有粒子（黑洞本身不缩）
const BH_PINCH_DUR = 0.42;      // ② 塌缩：黑洞本身缩小到中心点 + 引力扭曲动效
const BH_FLASH_DUR = 0.30;      // ③ 闪光
const BH_BURST_DUR = 0.95;      // ④ 爆发：放大到 BH_R_MAX（同时顶开碎块/基准面）
const BH_COLLAPSE_DUR = BH_SUCK_DUR + BH_PINCH_DUR + BH_FLASH_DUR + BH_BURST_DUR; // 2.65s
/* v5.23-form（用户定标，<80 回落三段，取代旧的 0.85s 一段缩）：
 * 用户原话："能量降下 0.8 阈值后，黑洞先塌缩成一个点，再膨胀到对应能量的大小，
 * 外壳在黑洞膨胀到对应大小后渐显（先出现数据流虚影，随着数据填充逐渐变为实体）到对应位置。"
 * ① crush ② bloom ③ form —— 面板只在 ③ 段成形，位置从内侧连续浮升到位，绝无瞬移。 */
const BH_RESURGE_CRUSH_DUR = 0.50;  // ① 被自身引力压进中心奇点（带引力扭曲）
const BH_RESURGE_BLOOM_DUR = 0.60;  // ② 从奇点膨胀到当前能量对应的尺寸（easeOutCubic）
const BH_RESURGE_FORM_DUR = 0.95;   // ③ 外壳数据化成形：数据流虚影 → 实体 + 浮升到位
const BH_RESURGE_DUR = BH_RESURGE_CRUSH_DUR + BH_RESURGE_BLOOM_DUR + BH_RESURGE_FORM_DUR; // 2.05s
/** v-内容4-形：外壳板中心到体心的距离 = **当前黑洞半径 + 0.1u**（用户定标），
 *  但不小于闭合态 BH_SHELL_IN —— 闭合时 12 块板正好拼成完整十二面体。 */
const bhPanelDist = (r) => Math.max(BH_SHELL_IN, r + BH_PANEL_GAP);

/* v-内容5：高能数据立方体粒子（核心外壳内的能量粒子云）。
 * 微小立方体，颜色随能量 0-100 渐变（冰蓝 → 橙黄 → 亮橙），速度越快拖尾越长。
 * 与黑洞体行为联动：0-20 自由缓慢随机移动（黑洞紧闭无法激发）；20-80 板壳缝隙渐大、
 * 粒子越来越频繁被吸入缝隙被黑洞吞噬（先选粒子 → 吸引 → 吞噬 → 回收：随机位置+
 * 随机初速度新粒子）；**>80 全部粒子被黑洞塌缩吸入（v-内容4-形：不再有两股环流）**；
 * 降回 <80 粒子散开均匀分布在核心壳体内绕中心旋转。 */
const DP_COUNT = 400;           // 粒子数
const DP_SIZE = 0.020;          // v5.25：立方体边长 0.045 → 0.020（用户："大小太大，称不上精密"）
const DP_TRAIL_W = 0.014;       // 拖尾宽度（u）
const DP_WANDER_SPD = 0.030;    // 自由游走速度（u/s）
const DP_INNER = 0.34;          // 粒子环带内半径（避开黑洞体外壳 + 余量）
const DP_OUTER = 0.66;          // v5.25：粒子环带外半径 0.78 → 0.66（用户："有些粒子超出核心外壳"）
const DP_INHALE_MAX = 10;       // 20-80 段 80 时的每秒吸入数
/* v-内容4-塌：>80 不再走"每秒名额"，而是**一次性把全部粒子转入 attract** 并在
 * 0 ~ 55%×BH_SUCK_DUR 内错峰被拽走 —— 保证"一定时间内被全部吸入，不重生"。 */
/* v-内容4-形：DP_FLOW_R1 / DP_FLOW_R2（>80 双股环流轨道半径）已随 flow 模式一并删除
 * —— 用户定标">80 是全部被吸入，不存在环流"。 */

/* ★ v-碎膜：**碎膜飞散**（用户构思）—— 跌破 80 时，外围那圈变白的碎块表面不再"瞬间褪白"，
 * 而是**白膜裂成一系列微小水晶碎片、往外剥离消散**。
 *   · 碎片形状与大小**来自各自碎块面的简化轮廓**（不是通用小方块）⇒ 每片形状都不同；
 *   · 因此**不能用 InstancedMesh**（它要求全部实例共享一份几何，装不下 285 种形状）
 *     ⇒ 走**动态顶点缓冲**：每个碎片把自己的轮廓顶点写进同一个 BufferGeometry ⇒ 仍是一次 draw call；
 *   · 碎片从**外缘环**产生 —— 只有那一圈会变白（数据粒子捕获池「_pickFragmentIndex」只在
 *     radialN ≥ 0.72 的外缘环里选片），与用户观察一致；
 *   · 与数据粒子（DP）是两套东西：DP 是能量粒子，这里是碎块白膜裂出的晶片。 */
const SHARD_MAX = 2300;           // 碎片池上限。★ v5.8.2：1400 → 2300 —— 用户定标"**每个白了的碎块面
                                  // 都要碎**"⇒ 需要量 = 外缘环片数（band3，≈60~132）× 每片 12~16
                                  // ≈ 720~2100 ⇒ 池必须够，否则后挑中的片会被静默丢弃。
                                  // ⚠⚠ **硬天花板 = 2340，不许再往上抬**：碎片几何的索引缓冲是
                                  // `Uint16Array`，索引 = `s * SHARD_PIECE_V + k`，最大 = `SHARD_MAX × 28 − 1`；
                                  // 超过 65535 会**静默回绕**（不报错、几何错乱）。2340×28−1 = 65519 是极限。
                                  // 池不足会**静默丢弃**（观测口 `_shardMissed`）；代价只有内存（≈7MB）
                                  // + 命中时的定长循环，draw call 恒为 2。
const SHARD_RING_N = 0.72;        // 只有 radialN ≥ 此值（= 捕获池覆盖的外缘环）才可能变白
const SHARD_PIECE_V = 28;         // 每块碎片的**最大顶点数**（动态缓冲按此定长）。
                                  // v5.4（B 方案）：顶点池布局从「[v0..v_{m-1}]」改成
                                  // 「[质心, v0, v1, …, v_{m-1}, b0(重复)]」—— 锚点必须是**块质心**
                                  // （胞是凸的 ⇒ 顶点平均必在块内），否则连最基础的
                                  // "心暗边亮/心到边的径向坐标"都拿不到（每块只有一圈边界点）。
                                  // 容量：胞 = 母片轮廓（≤ SHARD_HULL_MAX 条边）被最多
                                  // (SHARD_TILE_NMAX−1) 个半平面各裁一刀、凸多边形每刀净增 ≤1 顶点
                                  // ⇒ m ≤ 10 + 15 = 25；扇形锚点 = 质心 ⇒ 需 m + 2 = 27 顶点。
                                  // ★ v5.8：24 → 28（块数从 9 提到 16 之后，槽位必须够 27）。
                                  // 代价 = 每帧多变换 4 顶点/槽（仅爆发期可见，且 VERT 侧近免费）。
const SHARD_HULL_MAX = 10;        // 每片碎块**凸包轮廓**的顶点上限（重分网格的片包络点可能
                                  // 几十个 ⇒ 单调链求完凸包后等距抽稀到这个数）
const SHARD_LIFE_MIN = 0.90;      // 碎片生命下限（s）
const SHARD_LIFE_MAX = 1.40;      // 碎片生命上限（s）
const SHARD_OUT_SPD = 0.85;       // 沿面法线"往外剥离"的初速（u/s）。★ v3：0.55→0.85 ——
                                  // 太慢时位移只有 ~0.3u，贴在晶面上读不出"剥离"，像原地淡出。
const SHARD_SPREAD = 0.16;        // ★ v4 语义变更：块沿**自身朝外方向**的四散速度（u/s）——
                                  // 用户草图（四块各标 1/2/3/4、箭头各指一方）：裂开的块不是
                                  // 整体一起平移，而是各沿"片心→块心"的方向散开；另加少量
                                  // 切向抖动错开块与块。
/** ★ 掀开角（rad）：碎片绕**本片内缘的铰链线**从 0 向外掀到该角度 —— 这是"从面上向外剥离"
 *  的视觉主语。正交/小 FOV 下，沿法线的平移几乎就是沿视线 ⇒ 屏幕上根本不动；只有**姿态**的
 *  改变（轮廓被拍扁/转过去）才读得出来。★ 枢轴取"内缘"（片心 − t̂·半宽）而不是片心：
 *  绕自身中心转 = 两半反向翻 = 读成"碎屑翻滚"；绕内缘转 = 一条边钉住、另一边掀起来
 *  = 读成"舱门/膜片往外开"。 */
const SHARD_TILT_MAX = 1.15;
const SHARD_DRAG = 1.0;           // 阻尼（1/s）。★ v3：1.6→1.0 ⇒ 终止位移 ≈ 0.85u，明确离开晶面
const SHARD_SPIN_MAX = 2.2;       // 自转角速度上限（rad/s）。★ v4：8.0→2.2，且**出生相位 = 0**
                                  // —— 块出生那一刻必须与邻块拼合成完整白膜（"裂开"的前提），
                                  // 随机相位 + 快速自转会直接读成"一堆乱飞的碎屑"。
const SHARD_HDR = 0.24;           // 亮度增益（加色）。★ 定标史：1.45（整屏炸白）→ 0.55
                                  // （仍是一片"白色的片"）→ 0.24。加色是**叠加**：几百片同时
                                  // 可见时按"单片看着合适"定标必然过曝；而且它贴在本来就接近
                                  // 白饱和的晶面上，越亮越读不出形状 ⇒ 只能压到比母面更暗，
                                  // "剥离下来的那一层"才看得出来。
/** ★ v5.8.10 碎片**深度预Pass 孪生体**的层序（业界标准 depth prepass，见日志第 20 条）。
 *  · 本体（颜色层）= **33**（沿用原值）。
 *  · 孪生体（只写深度）必须**严格小于**本体，否则它后画、深度写晚了**遮不住任何东西**
 *    —— 这正是母片孪生体（35）> 碎片（33）的历史教训：碎片永远不会被母片孪生体挡住。
 *  · 取 **32**：与晶体本体/柱面/内芯同层（规则 5「同类物体必须同层」在**深度**语境下成立：
 *    它们都是"结构层"，而结构层之间本来就该互相遮挡），且**小于** 33。
 *  · ⚠ 改任何一层的 renderOrder 时必须回来看这个大小关系。 */
const SHARD_DEPTH_ORDER = 32;
/** ★ 结膜门槛（`cool` = u_cool 归一值 ≥ 此值才裂）。
 *  ★★ v5.8.2：0.85 → **0.18**（= `stored ≥ 1`，即"**被命中过一次 = 这一片有膜了**"）。
 *   为什么这次是"语义错"而不是"阈值调参"：
 *   · 命中分配由 `_buildHitQueue(ring, …)` 保证「每个转动间隔内，本面外圈**每片**至少一次」
 *     （见 _updateHitQueues），所以外圈每片都会攒到 `stored` —— 用户看到的是**整圈膜**；
 *   · 而 0.85 要求 `stored ≥ 4.7`（≈**同一片被命中 5 次**，需要站住 5 个转动窗口）⇒ 它筛掉的
 *     是"膜还不够厚"的片，**不是**"没膜的片" ⇒ 与用户"每个碎块的面都该碎"的诉求正好相反；
 *   · 膜**厚薄**本来就只该决定碎片的**亮度**（`cool` 已在做这件事），不该决定裂不裂。
 *  ⚠ 与 v1「stored > 0」的区别（当时被否过，为什么现在可以）：v1 是"挨过一两粒就裂"**且**
 *    每片只有 3/6/9 块、保险丝还是"按比例缩块数" ⇒ 满屏小碎片糊成一片白。现在每片 12~16 块、
 *    保险丝**按片数入选**且预算 = 外圈池需要量 ⇒ "整圈膜一起碎成晶片"是用户新定标的效果。
 *  ⇒ 教训（沿用）：**别拿"阈值落在饱和区哪一侧"解释"物体没出现"**；但反过来也成立 ——
 *    **别拿"调阈值"去修"数量不对"**，先问这个阈值的语义是不是错的。 */
const SHARD_COOL_MIN = 0.18;
/** 单次爆发**碎片总量预算上限**（白屏保险丝）。
 *  ★ v5.8：260 → 400，且**保险丝改口径**（原来"按比例缩每片的块数、保底 2 片"，现在"按白得
 *    最狠优先挑片、每片块数一个都不削"）。用户定标："碎片至少要分 10 块" ⇒ 块数不许被削，
 *    要控总量只能**少挑几片**。
 *  ★★ v5.8.2：400 → **1800**，而且**不再拿它当实际预算** —— 崩裂帧取
 *    `budget = min(SHARD_BURST_MAX, 外圈池片数 × 每片最多块数)`（见 _emitShardBurst）。
 *    为什么必须抬：用户定标"**每个白了的碎块面都要碎成很多片**"⇒ 需要量 = 外圈池（band3，
 *    约 60~132 片）× 12~16 ≈ 720~2100 块；而 400 只够 `400/12 ≈ 33 片` ⇒ 它本身就是
 *    "其余碎块根本没碎片出来"的第二条成因（第一条见 SHARD_COOL_MIN 的语义修正）。
 *  ★ 为什么加大总量不会更亮：碎块**精确拼合**母片 ⇒ 加色总量 ∝ 覆盖面积，跟切成几块无关；
 *    且膜薄的片 `cool` 低 ⇒ 碎片本身就暗，整圈一起碎不会把画面推白。
 *  ⚠ 上界受 SHARD_MAX 约束（Uint16 索引硬天花板 2340，见 SHARD_MAX 注）。 */
const SHARD_BURST_MAX = 1800;
const SHARD_TINT = [0.80, 0.90, 1.00];   // 碎片本体：冷蓝白（比纯白偏蓝 ⇒ 压在晶面上不会直接拉白）
/** ★ 拖尾色 = **白**（v5.1：用户定标 —— 不要青色流线，和碎片本体同一族白）。
 *  定标史：v3 青 [0.36,0.78,1.00]（"能量笔迹"）→ v5.1 纯白。 */
const SHARD_TRAIL_TINT = [1.00, 1.00, 1.00];
/** stored 分档 → **档位序号**（第二列 = SHARD_TILE_NS 的下标，不是块数本身）。
 *  ★ v5.8：块数从「3/6/9」改成「10/13/16」（用户："至少要分 10 块"）；门槛沿用 15/35/50
 *    ⇒ 门槛以下的片（stored 刚过结膜闸 4.7 的那批）现在也裂 **10** 块，不再是 3 块。
 *  门槛在 SHARD_COOL_MIN（不够白 = 没结膜 = 不裂）。 */
const SHARD_TIERS = [[15, 0], [35, 1], [50, 2]];
/** 出生时沿面法线的微小抬离（u）：碎片一出生就**离开**晶面一点点，
 *  否则第一帧它和母面完全重合、又都是加色白 ⇒ 看起来"不是从面上剥出来的"。 */
const SHARD_LIFT = 0.014;
const SHARD_TRAIL_LEN = 0.24;     // 拖尾长度**上限**（u）。实际长度按块自身尺寸定标（见 update）。
                                  // ★ v5.6：0.34 → 0.24 —— 用户实测把拖尾读成"细长条"：细长 =
                                  // 长且窄，先砍长（宽的根治见 update 里的"屏幕面内宽度"）。
const SHARD_TRAIL_W = 0.022;      // 拖尾宽度（u）。★ v5：0.010→0.022 —— 0.010u 在屏上只有 ≈2~3px，
                                  // 又贴在白膜上，等于没画。
const SHARD_TRAIL_ALPHA = 1.0;    // 拖尾亮度（相对本体）。★ v3 0.34→0.85，v5 →1.0（与本体同量级）
/** ★ v5 关键修正：拖尾整条沿 +nrm 抬这么多（u），保证它**浮在母面之上**。
 *  根因：旧版方向 = −vel，而 vel 的主导项是**面法线**（OUT_SPD 0.85 vs 切向 0.16）⇒ 尾巴往回伸
 *  0.22u 时碎片只抬离了 0~0.4u ⇒ 大半条沉到晶面以下，被 depthTest 的晶体几何整条剔掉（与规则 27
 *  同源：法线方向在正交相机下既不产生屏幕位移、也会被自己挡掉）⇒ 用户"一条都没看到"。
 *  现在方向先投影到**切平面**，再整体抬高 ⇒ 永不被母面遮挡、且必然有屏幕投影。 */
const SHARD_TRAIL_LIFT = 0.020;
/** ★ v5.6：整条再沿 **+Z（朝相机）** 抬这么多。相机是固定正交（视线恒 −Z）⇒ 这个抬升**在屏幕上
 *  零位移**，只改深度：把拖尾从壳面"拎"到相机这一侧 ⇒ 宽度方向改成屏幕面内之后（见 update），
 *  掠射角那部分带子也不会再被壳体 depthTest 削掉半条。可见面片沿 +Z 必然离开凸壳（可见点 =
 *  该视线进入壳体的入口，再往前就是壳外）。 */
const SHARD_TRAIL_ZLIFT = 0.030;

/* ==================== v5.4 碎膜**质感**（B 方案 · 见《碎片质感调研_2026-10-02.md》§5）====================
 * 用户："碎片只有一个色块，没有质感" —— 根因是本体走 MeshBasicMaterial + 逐顶点色，
 * 而顶点色**块内是同一个数**（发射时「TINT × bright」一次算完，块里 m 个顶点同值）
 * ⇒ 没有光照、没有棱面、没有边，屏上就是一撮平色片。
 *
 * 三条杠杆（调研 §2）：① 逐块**刻面法线** → envProc 的灯带在棱面上扫过（"活光"，最关键）；
 * ② **贴边一圈亮棱线**（晶片的"棱"，见 SHARD_RIM_P/SHARD_EDGE_K）；③ 面内微结构（#define 可整层消融）。
 *
 * ★ 亮度策略：**基底仍是顶点色**（= TINT × bright，死亡时归零 ⇒ 加色下"消失"，这条机制
 *   不能丢），着色器只乘一个**块内/块间调制因子** ⇒ 整体亮度与改前同级，拉开的是对比。
 *   定标（按 envProc 的实测取值域估）：天光底 0.008~0.05、水平环带 ~0.24、灯带峰 ~1.4；
 *   取"归一后的加性高光"模型 shade = BODY·(1 + K·env/(HL+env))：
 *     env→0 : 0.95（纯本体，不黑）   env 0.15 : 1.36   灯带峰 1.4 : 1.97
 *   ⇒ 不会出现"环境暗处碎片变黑"，亮带扫过时约 2 倍闪烁。单旋钮 = SHARD_ENV_K。 */
const SHARD_FACET_K = 0.50;       // 刻面法线混合量：N = mix(真实面法线, 每块随机方向, 此值)
                                  // 0 = 整块一个朝向（回到平色）；0.50 ≈ 最大偏 30°
                                  // ★ v5.5：0.30 → 0.50 —— 0.30 只偏 17°，相邻块的反射方向
                                  //   几乎一样（灯带要么都扫到、要么都扫不到）⇒ 块间没明暗差；
                                  //   0.50 才能让"有的块亮、有的块暗"真正看得出来。
const SHARD_ENV_HL = 0.30;        // envProc 归一化的半饱和常数（Reinhard 式压缩 ⇒ 不作黑）
const SHARD_ENV_K = 1.30;         // ★ 唯一旋钮：环境反射增益（越小越平，越大越闪）
const SHARD_BODY = 0.95;          // 环境反射 = 0 处的本体亮度倍数（保证背光棱面不黑）
const SHARD_RIM_P = 6.0;          // 边缘亮线的 pow 指数：越大亮线越细、越贴边
                                  // ★ v5.5：3 → 6 —— 3 的"边亮"摊在半径后半段，屏上读作
                                  //   "块内渐变"；6 才收成贴边 1~2px 的一条**轮廓亮线**，
                                  //   碎晶的"棱"就是靠它读出来的。
const SHARD_EDGE_K = 1.00;        // 边缘亮线的增益（边缘最亮 = (1 + 此值) 倍；0 = 关）
                                  // ★ v5.5 删掉旧 SHARD_RIM_BASE / SHARD_CRACK_DARK：
                                  //   旧"心暗边亮 + 沿裂缝暗带"是**减光**，而碎片是加色层，
                                  //   在已很亮的晶面上减掉 0.06 的加色 = 屏上几个灰阶 ⇒ 看不见。
                                  //   看得见的方向只有一个：**加**（贴边加亮，轮廓自己发光）。
const SHARD_SURF_GAIN = 1.15;     // 总体重定标（见上定标）
const SHARD_MICRO = true;         // false = 编译期消融"面内微结构"整层（规则 18 的手法）
const SHARD_MICRO_SCALE = 5.5;    // 微结构格子密度（块局部坐标 × 此值）
const SHARD_MICRO_K = 0.22;       // 微结构幅度（0 = 关）

/* ★★ v5.5 碎块改成「**长出来**」而不是「切出来」——三个旋钮 ──────────────────
 * 旧法（Voronoi 把母片切成 n 份）的结构性缺陷：**胞的形状被母片长宽比锁死**。
 * 母片（外圈环带）是 2~4:1 的长条 ⇒ 填满条宽的胞自身就有 2~4:1；边界胞更被包边
 * 斜切成长三角。v5.3 的闸门是"删掉细长胞让邻胞长大补"，但邻胞长大**又**变细长
 * ⇒ 删一批长一批，永远追不完（用户实测"还是有非常多的细长三角形"）。
 * 新法：每颗种子**自己长一块**各向同性的多边形小晶片（半径抖动 + 随机相位），
 * 半径取 min(按面积分摊的基准, 到包边距离×FIT) ⇒ **塞不进的地方自动缩小**，
 * 细长条从结构上不可能出现。 */
/* ★★ v5.7 **等面积分割**（power diagram / 加权 Voronoi）：把"能拼合"和"不出细长条"同时拿回来 ────
 * ★ 既定不变式（**不许再丢**）：白膜崩出来的碎块**必须能拼回原来那片碎片面** —— 块与块共享
 *   裂缝边、所有块合起来 = 母片轮廓（精确覆盖）。v5.5/v5.6 为了消灭细长条改成"每块自己长"，
 *   把这条不变式丢了（用户点名："这些白色碎片要能拼成原来的碎片面"）。
 *
 * 为什么普通 Voronoi 会出细长条、而"等面积"能治：普通 Voronoi 只保证"离谁近归谁"，**不保证面积**，
 * 一格被两边挤住的胞就摊成条；面积一旦拉平，长条母片里的胞会自动排成砖块阵 ⇒ 每块都敦实。
 * 做法 = 给每颗种子一个权重 w，把裁剪线从"垂直平分线"挪到"带权平分线"：
 *     |p−Sk|² − wk ≤ |p−Sj|² − wj   ⟺   p·n ≤ c， n = (Sj−Sk)/|Sj−Sk|，
 *     c = (|Sj|² − |Sk|² + wk − wj) / (2|Sj−Sk|)
 *   ⇒ **同一个 `_shardClipHalf`**，只是裁剪中点由 (Sk+Sj)/2 挪到 c·n。
 * 迭代：裁一遍 → 按面积误差调权重（增量重定心，只有差值有意义）→ 再裁 …… 直到各胞面积落进容限。
 * ⚠⚠ 权重是"加"进裁剪刀的 ⇒ **抬权 ⇒ 胞变大**（c 里带 `+wk`）。所以面积**超出**目标的胞必须
 *   **降权**（`w_k -= GAIN·err`）。★ v5.7 这里写成了 `+=`（连理由都记反了）⇒ **正反馈**：
 *   越大的胞越大、邻居被挤成 0 顶点 ⇒ 细长闸门把邻居全删掉 ⇒ pc 从 12 塌到 1~4，
 *   凸包偏长的片连最后一块都过不了闸门（`keep < 1 ⇒ return 0`）⇒ **整片不崩**。
 *   用户 v5.7「碎片太少了」与 v5.8「根本没有分出 10 片」都是这一条，**不是块数档位的问题**。
 *   v5.8 修正：更新方向取反 + 步长改阻尼（见 SHARD_TILE_GAIN 注）。w 与面积同量纲 ⇒ 步长 O(1)。
 * ⚠ 只做**权重**配平、**不做** Lloyd 重心松弛 —— Lloyd 会收敛成蜂窝六边形（用户刚否过"全是六边形"），
 *   权重配平保留不规则种子的布局 ⇒ 胞的形状/朝向/边数依旧五花八门。 */
const SHARD_TILE_PASS = 10;       // 每轮配平迭代上限（提前收敛即退出）
const SHARD_TILE_TOL = 0.30;      // 面积相对误差容限（各胞落进各自目标的 ±30% 即停）
/** ★★ v5.8 修正：权重步长 **0.90 → 0.45**（配合下面"更新方向反了"的修正一起改的）。
 *  一个胞的每条边界都由「到某个邻居的带权平分线」给出 ⇒ 抬权 δ 会把**每条**边界同时往外推
 *  ⇒ 面积响应 ∂A/∂w ≈ 2（正方形胞估法：周长 4s × 位移 δ/(2s) = 2δ）。
 *  · 原 0.90 ⇒ 迭代因子 |1 − 0.9·2| = 0.8 ⇒ **来回震荡**，10 趟都压不进 SHARD_TILE_TOL；
 *  · 0.45 ⇒ |1 − 0.45·2| = 0.1 ⇒ 两三趟收敛。
 *  单步上限仍由 SHARD_TILE_STEP 兜底（防初始大误差一步过冲）。 */
const SHARD_TILE_GAIN = 0.45;
const SHARD_TILE_STEP = 0.25;     // 单次权重修正上限（× 该胞目标面积）⇒ 防震荡
const SHARD_TILE_ROUND = 3;       // "删细长胞 → 重新配平"的最大轮数（删了种子必须重配，否则邻胞长大又变细）
/** ★ v5.8 种子最小间距²（× 面积/块数）—— 见 _shardPartitionN 的"抛镖采样"。
 *  越小 ⇒ 越容易扎堆（会出小屑、多几个被闸门删掉的胞）；越大 ⇒ 越像点阵（"切菜"的味道回来了）。 */
const SHARD_SEED_GAP = 0.25;
/** ★ v5.8 面积目标的**随机幅度**：每块目标面积 = 平均面积 × (1 ± 此值)。
 *  0 = 等面积（**用户否掉的"切菜等宽段"**）；0.55 ⇒ 最大块 / 最小块 ≈ 3.4:1 ⇒ 有大块有小屑。 */
const SHARD_TILE_SIZE_VAR = 0.55;
/** 细长闸门：q = 2·√面积/周长，越小越细长（正方形 0.50 / 等边三角形 0.44 / 1:3.5 ≈ 0.42 /
 *  1:5 ≈ 0.37 / 1:8 ≈ 0.31）。低于此值的胞**连种子一起删掉再配平** —— 它占的那块区域会被
 *  邻胞接管（仍是精确拼合，只是那一片归了隔壁）。 */
const SHARD_CHIP_CHUNK = 0.34;
/** ★ v5.8 **每片白膜按档位切几块**（索引 = 档位序号，档位见 SHARD_TIERS）。
 *  用户定标（v5.7 实测）："分的碎片太少了…… 碎片至少要分 10 块" ⇒ 最低档从 3 提到 12。
 *  ⚠ 这里填的是**请求块数**，不是最终块数：母片凸包的**尖角**处必然产生楔形胞，
 *    它们会被细长闸门（SHARD_CHIP_CHUNK）合并给邻居 ⇒ 最终块数通常比请求数少 1~3。
 *    所以请求数留了余量，最终落在 10~16（下限由 SHARD_TILE_MIN 兜底）。
 *  ⚠ 这个数组的第二列与 SHARD_TIERS 的第二列**必须一一对应**（tile 索引 = 档位序号）。 */
const SHARD_TILE_NS = [12, 14, 16];
const SHARD_TILE_N = SHARD_TILE_NS.length;                  // 每片烘 3 份（索引 = 档位序号）
const SHARD_TILE_NMAX = SHARD_TILE_NS[SHARD_TILE_N - 1];    // 单次请求上限 = 16（= PART_N，槽位上限）
/** ★ 用户硬地板：**每片至少崩 10 块**。少数凸包太尖、楔形被合并得太多时会跌破它 ⇒
 *  烘格期为这一档**放宽闸门重切一次**（见 _shardBakeTiles），宁可那一两块薄一点。 */
const SHARD_TILE_MIN = 10;
/** 预烘格**单胞**的顶点上限：胞 = 母片轮廓（≤ SHARD_HULL_MAX 顶）被最多 (NMAX−1) 个半平面裁，
 *  顶点数 ≤ `SHARD_HULL_MAX + (SHARD_TILE_NMAX − 1)` = 25。 */
const SHARD_TILE_V = SHARD_HULL_MAX + SHARD_TILE_NMAX - 1;
/** ★ 预烘格：胞的分割只依赖（母片轮廓, 块数）——两者都在加载期就定死了 ⇒ **加载时烘一次、
 *  崩裂帧直接查表**（崩裂帧内零迭代、零分配）。每片烘 `SHARD_TILE_N` 份（= 档位数）。 */

/* ★ 碎块分割（等面积 power diagram）的定长 scratch —— 模块级、加载期分配一次；
 * **只在加载期（预烘格）用**，崩裂帧只从 `this._shardTiles` 拷进这里 ⇒ 渲染帧内零分配
 * （见状态池同款约束：运行期 new 会造成 GC 抖动）。
 * 槽位约定：「_PART_POOL[0..pc-1]」= pc 个胞，**槽 PART_HULL 专门存母片轮廓**（裁剪时它必须
 * 保持不变）；pc ≤ SHARD_TILE_NMAX = 16 ⇒ 0..15 够用。每槽定长 SHARD_PIECE_V 个 (u,v)。 */
const PART_N = SHARD_TILE_NMAX;                           // 胞的槽数上限（0 .. PART_N-1）
const PART_HULL = PART_N;                                 // 母片轮廓专用槽（= 16，永不被写）
const _PART_POOL = new Float32Array((PART_N + 1) * SHARD_PIECE_V * 2);
const _PART_N = new Uint8Array(PART_N + 1);               // 各多边形的顶点数
const _PART_A = new Float32Array(SHARD_PIECE_V * 2 + 4);  // 半平面裁剪的输出缓冲
const _PART_S = new Float32Array(PART_N * 2);             // 种子点（每胞一个 (u,v)）
const _PART_W = new Float32Array(PART_N);                 // 各胞的**权重**（power diagram 用）
const _PART_T = new Float32Array(PART_N);                 // 各胞的**面积目标系数**（随机 ⇒ 有大块有小屑）

/** 内壳展开的 MainParam 阈值区间（激发态切换点） */
// v5.4：用户指定能量档位 —— <20 不显示分割线 / 20~80 显示切割线 / >80 展开
export const DEPLOY_START = 0.80;
// DEPLOY_END 已删除（v5.12）：展开位置不再由 smoothstep(p, 0.80, 0.97) 给出，
// 而是越过 0.80 触发**固定时长**的演出序列（爆发 → 碎块外推），与能量值解耦。

/* v5.12：0.80 之后的**固定时长演出序列**（全部与能量爬升快慢无关）
 *   ① SEAM_BURST_DUR：轮廓线爆发 —— 从脉冲当前位置向两侧铺满整个五边形面的轮廓，
 *      高亮一下再变暗。这是展开的"起手式"，先要把 XII 面体的轮廓线整体点亮宣示，
 *      再让碎块飞出；直接展开的话，观感上缺少这个蓄势。
 *   ② DEPLOY_DUR：碎块外推的长度。原先位置 = smoothstep(p, 0.80, 0.85) 是**能量的
 *      函数**（用户："现在的展开在 0.8-0.85 区间是固定位置的"）→ 改成 1/DUR 的固定
 *      速率推进，与云雾光环的成形同一套调度。 */
export const SEAM_BURST_DUR = 0.72;   // 铺满(0~0.42) → 高亮(0.42~0.62) → 变暗(0.62~1)
export const DEPLOY_DUR = 1.15;       // 碎块缓动到位

/* v5.13：装甲展开后碎块的「齿轮卡位」自转（用户定标）
 *  展开完成后，每块碎片每隔 2~4s（随机）绕**五边形面中心法线**顺/逆时针（随机）
 *  缓动旋转 72°（= 360/5，五边形的一次对称转动），先过冲 5~15° 再缓动回位 ——
 *  像齿轮卡进下一格。实现 = 缓动爬升的目标角 + 欠阻尼弹簧追踪：
 *  弹簧追一个 smoothstep 爬升到 72° 的目标，爬升结束时天然过冲再回位，
 *  过冲量由阻尼比控制（ζ≈0.45 → 过冲约 13~15°）。 */
export const FRAG_ROT_STEP = (Math.PI * 2) / 5;   // 72°
/* v5.13d（用户定标）：**旋转时间太长、过冲太小，体现不出齿轮卡位感**。
 *  ① 时长：基准 0.55s → **0.30s**，且改为"时长 = 基准 / 速率"（速率越大越快），
 *     以便让能量与片位置都作用在**速率**上；
 *  ② 过冲：注意时长与过冲**强耦合** —— 斜坡越接近阶跃输入，过冲越接近理论值
 *     72°·exp(-ζπ/√(1-ζ²))。缩短时长后先用 ζ=0.26~0.34，实测 23.9~26.3°
 *     （≈35% 过冲，偏橡胶感）；回调到 ζ=0.34~0.42 后实测 ~18°（≈25%），
 *     既有明确的卡位顿挫又不至于晃。要再调只动 ζ 一个数即可。 */
export const FRAG_ROT_RAMP = 0.30;                // 基准时长（秒）；实际 = RAMP / (片速率 × 能量加速)
/* v-内容2（用户修订）：**放弃阻尼弹簧模型**（zeta 欠阻尼 → 终点来回震荡才停），
 * 改为"过冲-齿轮卡位"解析两段式：
 *   · 驱动段：每片从当前角 easeOutCubic 冲到「终点 + 自己的过冲幅度」，顶点速度=0；
 *   · 回位段：从过冲顶点沿 cos 半周期被拉力（加速度 ∝ 偏离，即"偏离越大拉力越大"，
 *     回位前一直存在）拽回终点，到位瞬间**速度直接归零**（硬卡停，不震荡）。
 * 过冲幅度按 radialN 分档：面心片大、外缘片小（0=面心 1=外缘）→ 形成
 * "基准台→中心碎片→外围碎片"的内带动外层次。 */
/* v5.35（用户定标）："齿轮卡位现在实现了，但是因为过冲角度较小所以不是很明显……
 *   差不多是现在角度的两倍"。原 0.13 / 0.05 rad（7.4° / 2.9°）→ **0.26 / 0.10 rad
 *   （14.9° / 5.7°）**，正好 2×。
 * 参照系：一次卡位步进 FRAG_ROT_STEP = 72°，过冲/步进 = 20.7%（原 10.4%）；
 *   回位段时长不变（FRAG_RET_FRAC 0.38）⇒ 回位角速度也翻倍，"咔"得更明显。 */
export const FRAG_ROT_OVER_MAX = 0.26;            // 面心片过冲幅度（rad ≈ 14.9°，最大档）
export const FRAG_ROT_OVER_MIN = 0.10;            // 外缘片过冲幅度（rad ≈ 5.7°，最小档）
/** v-内容2：回位段时长 = 驱动段时长 × 该系数（短促有力，"咔"地卡住） */
export const FRAG_ROT_RET_FRAC = 0.38;
/* v5.13c/d：**缓动速率**（不是时长倍率）—— 走**面内归一化距离** radialN（0=面心 1=外缘）。
 * v5.13c 之前用世界单位 radial 做 `0.70+0.60*radial`，带宽只有 0.79~1.09 ——
 * 用户反馈"每个面的所有碎片缓动系数看起来也是一样的"。
 * v5.13d 起改为速率语义：面心片 1.45、外缘片 0.62（近 2.3× 档差），
 * 旋转读起来是一道从面心扫向边缘的波。 */
/* v5.35（用户定标）："缓动系数太大了，调小一点，现在看着和瞬移一样"。
 * 过冲翻倍后**角速度也跟着翻倍**（同样的时长要走更长的角度）⇒ 72° 的面心片在
 *   0.30 / (1.45 × 1.90) = **0.109s ≈ 6.5 帧**内走完（≈11°/帧）—— 这就是"瞬移"。
 * 调到 0.80 / 0.34（≈0.55×）后：
 *   · p=1.00（能量加成 ×1.90）：面心片 0.197s ≈ 12 帧（≈6°/帧）、外缘片 0.464s；
 *   · p=0.80（无加成）：面心片 0.375s、外缘片 0.882s —— 仍**快于** v5.13c 那版
 *     （RAMP 0.55s / 速率 ≈1.0 ≈ 0.55s），不会退回用户当年抱怨的"旋转时间太长"。
 * ★ 两个数的**比值**（2.35×）保持不变 ⇒ "波从面心扫向边缘"的层次感不受影响。
 * ★ 还有第二个旋钮：若单独觉得**回位那一下**太急，调 FRAG_RET_FRAC（回位时长 /
 *   驱动时长，现 0.38）；若觉得整体节奏（含基准台跟随）都慢/快，调 FRAG_ROT_RAMP。 */
export const FRAG_ROT_RATE_MIN = 0.34;            // 外缘片速率（慢）
export const FRAG_ROT_RATE_MAX = 0.80;            // 面心片速率（快）
/* v5.35：**驱动段（当前角 → 过冲顶点）缓动曲线的指数** = easeOutPow(EXP)。
 * "瞬移感"其实是两个来源，上面只解决了第一个：
 *   ① **时长太短**（角速度）—— 由 FRAG_ROT_RATE_* / FRAG_ROT_RAMP 决定，已放慢 1.8×；
 *   ② **曲线太前重** —— easeOutCubic(3.0) 在**前 20% 的时间里就走掉 49% 的角度**，
 *      起步那两帧几乎是从 0 跳到一多半 ⇒ 眼睛读到的就是一个"跳变"，而不是转动。
 *      降到 2.2 ⇒ 前 20% 只走 37%，起步明显放缓，末端仍平滑收敛（EXP>1 ⇒ 顶点速度=0，
 *      "冲到过冲顶点时速度恰好为 0"这条设计约束不受影响）。
 * 想更线性就继续往 1 调（1 = 匀速），想更"啪"就往 3 调。 */
export const FRAG_ROT_DRIVE_EXP = 2.2;
/* v5.35：回位段（过冲顶点 → 终点）**没有动** —— 用户只点了"旋转到过冲角度"这一段。
 * FRAG_RET_FRAC 仍是 0.38（回位时长 = 驱动时长 × 0.38，现 ≈0.075s），保持"咔"的短促。
 * 若单独觉得回位那一下太急/太拖，只调这一个数。 */
/** v5.13d：能量超出 0.80 的部分带来的**速率加成**（p=1.0 时 ×(1+0.90)=1.90） */
export const FRAG_ROT_ENERGY = 0.90;
/** v5.13c：回归演出的兜底超时（秒）—— 正常靠"全部碎片停稳"结束 */
export const FRAG_RET_TIMEOUT = 2.2;
/** v5.13d：能量掉下阈值后，**最多**冻结收拢这么久就开始降（用户：等半秒不到就回落） */
export const FRAG_RET_HOLD = 0.45;

/* —— v5.19：首次转动的排期（修"所有面同时转动一次"）——
 * 根因（探针 g16a 实测）：grp.nextAt 是**绝对时刻**，而能量 <80 期间转动触发条件
 * 根本不参与判定，nextAt 就一直停在很久以前的值（实测 1.79~3.79，而展开到位时
 * simTime 已到 6.48）。于是 d 一越过 0.98，12 个面全部满足 simTime >= nextAt
 * → 同一帧一起转（实测 12 个面首次激活时刻全是 6.48，spread = 0）。
 * 修正：在"刚具备资格"的上升沿按**当前时刻**重新排期。
 * · ROT_FIRST_DELAY_BASE：展开到位后最短等多久才允许转（留出"刚升起来"的读秒）；
 * · ROT_FIRST_STAGGER：12 个面首次转动摊开的窗口（分层随机分槽，不是纯随机）。 */
export const ROT_FIRST_DELAY_BASE = 0.30;
export const ROT_FIRST_STAGGER = 2.60;

/** v5.7：能量越过 DEPLOY_START 后，环状雾带的成形动画时长（秒，固定值） */
export const RING_FORM_DUR = 1.0;

/** v5.9：水晶轮廓线的能量阈值（<20 无分割线）与一次性渐显时长（秒，固定值）
 *  v5.16（本轮用户重排阈值）：轮廓线"从中心向外蔓延 + 沿轮廓循环高亮脉冲"整体
 *  后移到 **35** 阈值 —— 那才是用户要的"新 35"。原 20 阈值改由水晶壳的**面心脉冲渐显**
 *  承担（见 SHELL_SHOW_P）。 */
export const SEAM_SHOW_P = 0.35;
export const SEAM_FADE_DUR = 0.9;

/* —— v5.16：20 阈值 —— 完整水晶壳由每个基准面中心向外"不规则脉冲渐显" ——
 * 用户原话："能量上升到达20阈值时：完整的水晶壳通过在每个基准面中心由内向外
 * 不规则脉冲渐显，此时每个面的水晶是完整块。"
 * 与轮廓线（35）分工明确：20 = 晶体壳**出现**（整块、无轮廓线）；35 = 轮廓线**蔓延**。
 * 前沿同样是空间径向的（面内 rt 0=面心 → 1=五边形边界），一次性，固定时长，
 * 反向（能量跌回 20 以下）同速收回。 */
export const SHELL_SHOW_P = 0.20;
export const SHELL_FORM_DUR = 0.75;
/* v5.31：前沿行程的**端点**（GLSL 镜像在公共块 SHELL_FRONT_GLSL）。
 * CPU 侧需要它来判断"前沿正跨过哪几片"→ 只给那几片打开柱面（其余柱面 visible=false）。 */
export const SHELL_FORM_START = -0.20;
export const SHELL_FORM_END = 1.35;
/** 水晶壳前沿的软边宽度（半径占比）与推进缓动指数：1.35 次幂 → 面内可见时长占 63% */
export const SHELL_FORM_SOFT = 0.14;
/** 水晶壳前沿自带的一道"脉冲亮边"增益（渐显是"脉冲"，不是单纯淡入） */
/* v5.31b：2.00 → **1.45**（用户："顶面的脉冲线也很粗，都要改细"）。
 * 与宽度一起降 = 直接降喂给 bloom 的**总能量**（≈峰值 × 宽度）：0.018 → 0.007（约 39%）。
 * 峰值仍 >1.0 ⇒ 线还是亮、还是锐，只是不再糊成一圈笔触。GLSL 镜像见 FRAG 同名 #define。 */
export const SHELL_FORM_EDGE = 1.45;
/* v5.21：**前沿脉冲线的周长补偿** —— 修"脉冲线都到达边缘的时候亮度叠加会闪一下"。
 * crystalBand 是逐像素固定峰值 1.0，而折线的**屏幕弧长 ∝ 前沿半径**（面心处几乎是一个点，
 * 五边形边界处是整圈周长）。于是总光通量随前沿线性增长 → 到边缘时最亮 → 一次过冲闪光，
 * 越过 bloom 阈值 1.0 还会把整面糊白（与 v5.20"过曝糊成一团"同一根因）。
 * 补偿后单位长度增益 = 1/(1 + SHELL_ARC_COMP * front01)：front=0 → 1.00，front=1 → 1/(1+C)。
 * 1.15 → 边缘处单位亮度降到 46%，全程总光通量基本持平。 */
export const SHELL_ARC_COMP = 1.15;
/* v5.21：**断裂侧壁在 u_deploy=0 时的反光下限** ——
 * 渐显渐隐（u_shell_form 0→1）整段都发生在 u_deploy=0，而断口反光项原来乘了 u_deploy
 * → 侧壁被乘成 0，晶体板只剩一个没有厚度的平面五边形。
 * 用户原话："你现在渐显渐隐过程中画的两个面中间我没有看到任何侧壁"。
 * 0.55 = 内部裂纹侧壁的常驻档（压住 v5.5 修掉的"低能态暗轮廓线"）；
 * 外圈侧壁另有 1.7 的加成（见片元里 wallOuter），读作五棱柱真正的柱面。 */
export const WALL_AMP_FLOOR = 0.55;
/** v5.21：侧壁显现门控 wallVis 的下限（原 smoothstep(0.02,0.30,u_deploy) 在渐显段恒为 0） */
export const WALL_VIS_FLOOR = 0.60;

/* ==================================================================== *
 *  v6 步 2 · 晶体学区 + 生长扇区（设计提案 P1 → 步 2b 修正）
 *
 *  历史病根 = 把结构放进**加色通道**（v5.11 自认"填平元凶"；v5.18 探针实测内芯冷光均匀度
 *  std/mean = 3.11 = 雾，轮廓线 11.6 = 线）⇒ 结构只能走 mul/attenuation 或**方向**。
 *
 *  ⚠ 步 2b 修正（实测教训，已成规则 21/22）：初版把学区**只**喂 σ，实机"看不出任何变化"。
 *  根因不是接线而是通道：本片板厚 0.030±0.012、路径 = 厚度/max(0.32,ndv) ⇒ τ = σ·path ≈ 0.2
 *  ⇒ absorb ≈ 0.72~0.94 **处处≈1**（σ 改 ±55% 只让 absorb 动 ~10%，级联后只剩 2~5 灰阶）。
 *  而同 program 内的 L06（c *= 0.26+0.74·key^1.25）一眼可见 ⇒ **差别在通道，不在幅度**。
 *  ⇒ 学区改为三层协同：L01a **方向**（法线微扰，借 L01/L02 环境成像 + L06 主光）、
 *    L03a σ（保留：物理归属正确，τ 抬升后自动生效）、L04a **c 乘性**（无条件保底可见）。
 *
 *  对齐依据（不是新发明的形状，而是把**基准面已有的**结构线搬到碎块上）：
 *   · 环半径 0.30 / 0.66 —— 与 panelHeight() mode-0 的 sdPentagon(uv, apo*0.30 / apo*0.66)
 *     **逐点等价**：碎块的 t = vCrackUV.x 由 dodecaKit 的 warp 用 r = T·rB(A) 归一化
 *     ⇒ t 的等值线本身就是同心五边形，t = R ⇔ 内切半径 apo·R 的那个五边形。
 *     （dodecaKit 注释里的 "0.62" 是旧值；实际渲染的是 GLSL 侧的 0.66。）
 *   · 辐条方向 = 五边形**顶点**方向 = u_band_phi0 − 36° + k·72°
 *     （phi0 = 边法线起始角；顶点方位 = 边法线 −36°，与 dodecaKit 的 vertAz 同相位。）
 *
 *  ★ 与项目旧的「GLSL #define + JS 侧镜像双写」惯例不同：本组常量只用**模板插值单向注入**
 *    FRAG（单一真源），不存在"改一边忘了另一边"的漏改面。
 * ==================================================================== */
/** 内环半径（归一化）—— 0.30 与基准面 d2 同心五边形重合 */
export const CRYST_ZONE_R1 = 0.30;
/** 外环半径（归一化）—— 0.66 与基准面 d1 同心五边形重合 */
export const CRYST_ZONE_R2 = 0.66;
/** 环的半宽（归一化半径单位）；0.030 与 vCrystalNoise 噪声的最小格子同量级 */
export const CRYST_ZONE_W = 0.030;
/** 辐条角向半宽：用「Δa · t」度量 ⇒ 弧长近似恒定，面心不会糊成一团 */
export const CRYST_SPOKE_W = 0.055;
/** 环/辐条处的额外吸收：σ 乘 (1 + amt·zone) ⇒ 纹路更"实"、更暗 */
